class Solution:
    def countKConstraintSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        count = 0
        left = 0

        for right in range(n):
            while (s[left] == '1' and s[right] == '1') and (right - left + 1) > k:
                left += 1

            # Count valid substrings ending at 'right'
            # A substring s[left...right] is valid if:
            # - number of 0's <= k, OR
            # - number of 1's <= k
            # Since k <= n, we can check this by counting 0s and 1s

            zeros = 0
            ones = 0
            for i in range(left, right + 1):
                if s[i] == '0':
                    zeros += 1
                else:
                    ones += 1

            if zeros <= k or ones <= k:
                count += (right - left + 1)

        return count
```

