        n = len(nums)
        if k >= n - 1:
            return n

        # Sort the array to process duplicates together
        nums_sorted = sorted(nums)

        # Compute lengths of consecutive runs of duplicates
        run_lengths = []
        i = 0
        while i < n:
            j = i
            while j < n and nums_sorted[j] == nums_sorted[i]:
                j += 1
            run_lengths.append(j - i)
            i = j

